"@enterprise_only
def delete(self) -> None:
    """
    Delete the base.

    Usage:
        >>> base = api.base("appMxESAta6clCCwF")
        >>> base.delete()
    """
    try:
        self.api.delete(self.meta_url())
    except HTTPError as e:
        if e.response.status_code == 404:
            raise ValueError("Base cannot be deleted")
        else:
            raise e"

