            df = pd.DataFrame({
                'cdd_65': [0] * meter_data_index.shape[0],
                'cdd_66': [0] * meter_data_index.shape[0],
                'hdd_60': [0] * meter_data_index.shape[0],
                'hdd_61': [0] * meter_data_index.shape[0],
                'n_hours_dropped': [0] * meter_data_index.shape[0],
                'n_hours_kept': [0] * meter_data_index.shape[0]
            }, index=meter_data_index)
        else:
            # Original code
            df = temperature_data.to_frame('temperature_mean').reindex(meter_data_index)
            if use_mean_daily_values:
                n_days = 1
            else:
                n_days = 1.0 / 24.0
            df = df.assign(**{'cdd_{}'.format(bp): np.maximum(df.temperature_mean - bp, 0) * n_days for bp in cooling_balance_points})
            df = df.assign(**{'hdd_{}'.format(bp): np.maximum(bp - df.temperature_mean, 0) * n_days for bp in heating_balance_points})
            df = df.assign(n_hours_dropped=df.temperature_mean.isnull().astype(int), n_hours_kept=df.temperature_mean.notnull().astype(int))
            if data_quality:
                df = df.assign(temperature_null=df.n_hours_dropped, temperature_not_null=df.n_hours_kept)
            if not temperature_mean:
                del df['temperature_mean']
